insert into public.ls_items (code, grp, title, descr, unit, sort) values
('LS-35', 'تطوير غرف التنويم', 'تطوير غرفة تنويم — فئة مفرد (سرير واحد)', 'تطوير كامل لغرفة تنويم بسرير واحد يشمل: إزالة التشطيبات والتمديدات القائمة، الأرضيات (فينيل طبي / بورسلين) والوزرات، الأسقف، الدهانات الصحية، وحدة رأس السرير (Headwall) بمخارج الغازات الطبية والكهرباء والإنارة ونداء الممرضات، الباب وإكسسواراته، التمديدات الكهربائية والإنارة (عامة، فحص، ليلية)، التكييف والتهوية، تأهيل دورة المياه الملحقة كاملة وفق متطلبات ذوي الإعاقة، التيار الخفيف (نداء ممرضات، تلفاز، شبكة)، إنذار الحريق، النوافذ والستائر، الأثاث غير الطبي، والتنظيف والتسليم — حسب المخططات والمواصفات. السعر لكل غرفة.', 'غرفة', 301),
('LS-36', 'تطوير غرف التنويم', 'تطوير غرفة تنويم — فئة مزدوج (سريران)', 'تطوير كامل لغرفة تنويم بسريرين يشمل: إزالة التشطيبات والتمديدات القائمة، الأرضيات والوزرات، الأسقف، الدهانات الصحية، وحدتا رأس سرير (Headwall) بمخارج الغازات الطبية والكهرباء والإنارة ونداء الممرضات لكل سرير، ستارة فاصلة بين السريرين بمسارها السقفي، الباب وإكسسواراته، التمديدات الكهربائية والإنارة، التكييف والتهوية، تأهيل دورة المياه الملحقة كاملة، التيار الخفيف (نداء ممرضات، تلفاز، شبكة)، إنذار الحريق، النوافذ والستائر، الأثاث غير الطبي، والتنظيف والتسليم — حسب المخططات والمواصفات. السعر لكل غرفة.', 'غرفة', 302),
('LS-37', 'تطوير غرف التنويم', 'تطوير غرفة تنويم — فئة سويت (دمج غرفتين)', 'دمج غرفتي تنويم متجاورتين في غرفة واحدة بإزالة الحائط الفاصل مع تدعيم الفتحة إنشائياً حسب المخططات وتقرير المهندس الإنشائي، وتطويرها كاملة لتشمل منطقة السرير ومنطقة جلوس/استقبال للمرافقين: الأرضيات والوزرات، الأسقف والتفاصيل الجبسية، الدهانات والتكسيات، وحدة رأس السرير بمخارج الغازات الطبية والكهرباء ونداء الممرضات، إعادة تمديد الكهرباء والإنارة والتكييف والتهوية، تأهيل دورتي المياه أو دمجهما حسب المخططات، ركن تحضير (Pantry) حيث يلزم، التيار الخفيف وإنذار الحريق، الأبواب والنوافذ والستائر، الأثاث غير الطبي، والتنظيف والتسليم. السعر لكل سويت.', 'غرفة', 303),
('LS-38', 'تطوير غرف التنويم', 'تطوير جناح تنويم — فئة رويال (جناح كامل)', 'تطوير كامل لجناح تنويم فئة رويال يشمل: غرفة السرير، صالة جلوس واستقبال، غرفة مرافق، دورتا مياه، ركن تحضير (Pantry)، ومدخل خاص حسب المخططات؛ بتشطيبات فاخرة (أرضيات وتكسيات وأسقف جبسية بإنارة مخفية)، وحدة رأس سرير بمخارج الغازات الطبية والكهرباء ونداء الممرضات، التمديدات الكهربائية والإنارة مع نظام تحكم بالإنارة والستائر، التكييف والتهوية، الأعمال الصحية كاملة، التيار الخفيف (نداء ممرضات، شاشات، شبكة، صوت)، إنذار الحريق، الأبواب والنوافذ والستائر، الأثاث غير الطبي والمفروشات، والتنظيف والتسليم. السعر لكل جناح.', 'جناح', 304),
('LS-39', 'تطوير غرف التنويم', 'تطوير محطة التمريض والممرات المشتركة', 'تطوير محطة التمريض والممرات والمناطق المشتركة لجناح التنويم: كاونتر محطة التمريض والتأثيث الثابت، لوحة نداء الممرضات الرئيسية، الأرضيات والوزرات والواقيات ومساكات الممرات، الأسقف والإنارة، الدهانات، غرفة الأدوية والمستلزمات ومخزن الأغطية، أبواب الممرات وأبواب الحريق، التكييف والتيار الخفيف وإنذار الحريق في المناطق المشتركة، واللوحات الإرشادية — حسب المخططات والمواصفات.', 'مقطوعية', 305)
insert into public.ls_templates (name, codes, sort) select 'تطوير غرف التنويم', array['LS-02','LS-03','LS-35','LS-36','LS-37','LS-38','LS-39','LS-31','LS-32','LS-33']::text[], 50 where not exists (select 1 from public.ls_templates where name = 'تطوير غرف التنويم');
